// Raster-Komponente für Produkte
const ProductGrid = React.memo(
  ({ products, loading, error, onLike, onDislike, likedProducts, loadMore, hasMore, showMore, setShowMore }) => {
    const observer = useRef();
    const lastProductRef = useCallback(
      (node) => {
        if (loading || !hasMore) return;
        if (observer.current) observer.current.disconnect();
        observer.current = new IntersectionObserver(
          (entries) => {
            if (entries[0].isIntersecting) loadMore();
          },
          { rootMargin: '100px' }
        );
        if (node) observer.current.observe(node);
      },
      [loading, hasMore, loadMore]
    );

    if (loading && !products.length) {
      return (
        <div className="flex flex-col items-center py-16 min-h-[400px]">
          <div className="relative">
            <Loader2 className="w-16 h-16 text-amber-600 animate-spin" />
            <Sparkles className="w-6 h-6 text-amber-400 absolute top-0 right-0 animate-pulse" />
          </div>
          <span className="mt-6 text-amber-800 text-xl font-medium">Wir finden tolle Geschenke für dich...</span>
        </div>
      );
    }

    if (error) return <Alert>{error}</Alert>;

    if (!products.length)
      return (
        <div className="text-center py-16 min-h-[400px] bg-amber-50/50 rounded-xl border-2 border-amber-100">
          <Gift className="w-20 h-20 text-amber-300 mx-auto mb-6" />
          <p className="text-amber-800 text-xl font-medium mb-2">Keine Geschenke gefunden</p>
          <p className="text-amber-700/70">Versuche es mit anderen Filtereinstellungen</p>
        </div>
      );

    const initialProducts = products.slice(0, 8);

    return (
      <div className="flex flex-col items-center min-h-[400px]">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-8 w-full">
          {(showMore ? products : initialProducts).map((p, index) => (
            <div
              key={p.id}
              ref={index === (showMore ? products.length : initialProducts.length) - 1 ? lastProductRef : null}
              className="transform transition-all duration-300"
            >
              <ProductCard
                product={p}
                onLike={onLike}
                onDislike={onDislike}
                likedProducts={likedProducts}
              />
            </div>
          ))}
        </div>
        {!showMore && products.length > 8 && setShowMore && (
          <div className="mt-12">
            <button
              onClick={() => setShowMore(true)}
              className="px-8 py-3.5 bg-gradient-to-r from-amber-500 to-amber-600 text-white rounded-full hover:from-amber-600 hover:to-amber-700 transition-all duration-300 focus:outline-none font-bold min-w-[240px] text-center shadow-lg hover:shadow-xl transform hover:translate-y-[-2px] flex items-center justify-center mx-auto"
            >
              <Sparkles className="w-5 h-5 mr-2" />
              Weitere Geschenke anzeigen
            </button>
          </div>
        )}
        {loading && showMore && (
          <div className="py-8">
            <Loader2 className="w-10 h-10 text-amber-600 animate-spin" />
          </div>
        )}
      </div>
    );
  }
);

